<script>(function(){var s=document.getElementById('reparada'),d=document.getElementById('descripcion_reparacion'),r=document.getElementById('reparacionObligatoria');function validar(){var si=s&&s.value==='SI';if(d)d.required=!!si;if(r)r.style.display=si?'inline':'none';}if(s)s.addEventListener('change',validar);validar();})();</script>
<?php if($a['categoria_codigo']==='SERVIDOR'): ?><script>
(function(){var wrap=document.getElementById('discos');function enlazar(){wrap.querySelectorAll('.quitar-disco').forEach(function(b){b.onclick=function(){if(wrap.querySelectorAll('.disco-row').length>1)b.closest('.disco-row').remove();};});}document.getElementById('agregar-disco').onclick=function(){var row=wrap.querySelector('.disco-row').cloneNode(true);row.querySelectorAll('input').forEach(function(i){i.value='';});wrap.appendChild(row);enlazar();};enlazar();})();
</script><?php endif; ?>
